import { ethers } from 'ethers';
const RPC = "https://eth-sepolia.g.alchemy.com/v2/BBqgWCw5DmqAkIKhZfT0h";
const provider = new ethers.JsonRpcProvider(RPC);

const data = "";
const TO = "0xc8596bbbF270C4E54752ddE1D4b4e67F81b9b4F0";
const FROM = "0x53a3ed1d3512a40350d446c7b625B634014f6FC0";

async function main() {
    try {
        const gas = await provider.estimateGas({
            from: FROM,
            to: TO,
            data: data,
            value: 20000000000000000n // 0.02 ETH
        });
        console.log("Estimated Gas:", gas.toString());
    } catch(e) {
        console.error("estimateGas reverted!");
        console.error(e);
        
        try {
            await provider.call({
                from: FROM,
                to: TO,
                data: data,
                value: 20000000000000000n // 0.02 ETH
            });
            console.log("Call didn't revert but estimateGas did?");
        } catch(e2) {
            console.error("eth_call reverted too:");
            console.error(e2.message);
        }
    }
}
main();
